#include <iostream>
#include <string>
#include <iomanip>

class CommissionEmployee {
public:
    CommissionEmployee(std::string first, std::string last, std::string ssn, double sales, double rate)
        : firstName(std::move(first)), lastName(std::move(last)), socialSecurityNumber(std::move(ssn)),
          grossSales(sales), commissionRate(rate) {}

    virtual ~CommissionEmployee() = default;

    virtual double earnings() const {
        return grossSales * commissionRate;
    }

    virtual void print() const {
        std::cout << "commission employee: " << firstName << " " << lastName
                  << "\nsocial security number: " << socialSecurityNumber
                  << "\ngross sales: " << grossSales
                  << "\ncommission rate: " << commissionRate;
    }

private:
    std::string firstName;
    std::string lastName;
    std::string socialSecurityNumber;
    double grossSales;
    double commissionRate;
};

class BasePlusCommissionEmployee : public CommissionEmployee {
public:
    BasePlusCommissionEmployee(std::string first, std::string last, std::string ssn,
                               double sales, double rate, double salary)
        : CommissionEmployee(std::move(first), std::move(last), std::move(ssn), sales, rate),
          baseSalary(salary) {}

    double earnings() const override {
        return getBaseSalary() + CommissionEmployee::earnings();
    }

    void print() const override {
        std::cout << "base-salaried ";
        CommissionEmployee::print();
        std::cout << "\nbase salary: " << baseSalary;
    }

    double getBaseSalary() const { return baseSalary; }

private:
    double baseSalary;
};

int main() {
    std::cout << std::fixed << std::setprecision(2);

    CommissionEmployee baseEmp("Sue", "Jones", "222-22-2222", 10000.0, 0.06);
    BasePlusCommissionEmployee derivedEmp("Bob", "Lewis", "333-33-3333", 5000.0, 0.04, 300.0);

    CommissionEmployee* ptr = &baseEmp;
    std::cout << "Aiming at base-class object:\n";
    ptr->print();
    std::cout << "\n\n";

    ptr = &derivedEmp;
    std::cout << "Aiming at derived-class object:\n";
    ptr->print();
    std::cout << std::endl;

    return 0;
}

#include <iostream>
#include <memory>

class ResourceOwnerBase {
public:
    ResourceOwnerBase() {
        std::cout << "ResourceOwnerBase constructor\n";
    }

    // Virtual destructor ensures proper cleanup of derived classes
    virtual ~ResourceOwnerBase() {
        std::cout << "ResourceOwnerBase destructor\n";
    }

    virtual void process() const {
        std::cout << "Processing in base\n";
    }
};

// Marked final: cannot be derived further
class DerivedFinal final : public ResourceOwnerBase {
public:
    DerivedFinal() {
        std::cout << "DerivedFinal constructor\n";
    }

    ~DerivedFinal() override {
        std::cout << "DerivedFinal destructor\n";
    }

    void process() const override {
        std::cout << "Processing in DerivedFinal\n";
    }
};

int main() {
    std::cout << "--- Allocating dynamically through base pointer ---\n";
    ResourceOwnerBase* polyPtr = new DerivedFinal();

    std::cout << "--- Invoking virtual function ---\n";
    polyPtr->process();

    std::cout << "--- Deleting through base pointer ---\n";
    delete polyPtr;

    return 0;
}
